<template><section><div class="page-head"><div><h2>Manajemen Kelas</h2><p>{{ classes.length }} kelas · SMP & SMK · Tahun ajaran 2026/2027</p></div><button class="btn btn-primary btn-sm" type="button" @click="notice = 'Form tambah kelas tersedia saat backend resmi dimulai.'"><AdminIcon name="plus" size="16" /> Tambah Kelas</button></div><div class="grid g3"><button v-for="item in classes" :key="item.name" class="card" type="button" style="text-align:left;transition:.18s" @click="selected = item"><div class="card-b"><div style="display:flex;justify-content:space-between;gap:8px;margin-bottom:12px"><b style="font-size:17px">{{ item.name }}</b><span class="pill" :class="item.level === 'SMP' ? 'p-blue' : 'p-violet'">{{ item.level }}<template v-if="item.major"> · {{ item.major }}</template></span></div><div class="row-user" style="margin-bottom:14px"><span class="ava">{{ initials(item.teacher) }}</span><div><div class="t-name">{{ item.teacher }}</div><div class="t-sub">Wali Kelas · {{ item.room }}</div></div></div><div class="grid" style="grid-template-columns:repeat(3,1fr);gap:8px;text-align:center"><div class="stat-mini"><b>{{ item.students }}</b><span>Siswa</span></div><div class="stat-mini"><b>{{ item.boys }}/{{ item.girls }}</b><span>L / P</span></div><div class="stat-mini"><b>{{ item.average }}</b><span>Rata² nilai</span></div></div><div style="display:flex;justify-content:space-between;font-size:12.5px;margin:14px 0 6px"><span style="color:var(--muted)">Kehadiran hari ini</span><b style="color:var(--green)">{{ item.attendance }}%</b></div><div class="prog"><i :style="{ width: `${item.attendance}%`, background: 'linear-gradient(90deg,#22c55e,#16a34a)' }" /></div></div></button></div><p v-if="notice" role="status" style="margin-top:16px;color:var(--muted)">{{ notice }}</p><div v-if="selected" class="modal-ov" @click.self="selected = null"><div class="modal" role="dialog" aria-modal="true"><div class="modal-h"><h3>Kelas {{ selected.name }}</h3><button class="icon-btn" type="button" aria-label="Tutup" @click="selected = null"><AdminIcon name="x" size="17" /></button></div><div class="modal-b"><div class="row-user"><span class="ava">{{ initials(selected.teacher) }}</span><div><b>{{ selected.teacher }}</b><div class="t-sub">Wali Kelas · {{ selected.room }}</div></div></div><div class="stat-mini" style="margin-top:16px"><b>{{ selected.students }} siswa</b><span>Data peserta didik kelas ini akan membaca Data Induk pada Tahap 2.</span></div></div><div class="modal-f"><button class="btn btn-ghost btn-sm" type="button" @click="selected = null">Tutup</button></div></div></div></section></template>
<script setup lang="ts">definePageMeta({ layout: 'admin' }); type ClassData={name:string;level:'SMP'|'SMK';major?:string;teacher:string;room:string;students:number;boys:number;girls:number;average:string;attendance:number}; const classes:ClassData[]=[{name:'IX-A',level:'SMP',teacher:'Budi Santoso',room:'Ruang 201',students:30,boys:15,girls:15,average:'82.4',attendance:96},{name:'VIII-B',level:'SMP',teacher:'Siti Khadijah',room:'Ruang 202',students:29,boys:14,girls:15,average:'80.7',attendance:93},{name:'X RPL 1',level:'SMK',major:'RPL',teacher:'Ahmad Subarjo',room:'Lab RPL',students:32,boys:20,girls:12,average:'83.6',attendance:97},{name:'XI TKJ 1',level:'SMK',major:'TKJ',teacher:'Dewi Lestari',room:'Lab Jaringan',students:31,boys:22,girls:9,average:'81.9',attendance:90}]; const selected=ref<ClassData|null>(null); const notice=ref(''); const initials=(value:string)=>value.split(' ').slice(0,2).map(item=>item[0]).join('')</script>
